enhancedROCBase <- if (requireNamespace("jmvcore", quietly=TRUE)) R6::R6Class(
    "enhancedROCBase",
    inherit = jmvcore::Analysis,
    public = list(
        initialize = function(options, data=NULL, datasetId="", analysisId="", revision=0) {
            super$initialize(
                package = "ClinicoPath",
                name = "enhancedROC",
                version = c(1,0,85),
                options = options,
                results = enhancedROCResults$new(options=options),
                data = data,
                datasetId = datasetId,
                analysisId = analysisId,
                revision = revision,
                pause = NULL,
                completeWhenFilled = FALSE,
                requiresMissings = FALSE,
                weightsSupport = 'auto')
        }))

#' Clinical ROC Analysis
#'
#' Clinical ROC analysis toolkit for comprehensive diagnostic performance 
#' evaluation. Includes ROC curve analysis, Youden Index optimization, 
#' sensitivity/specificity analysis, optimal cutoff determination, and 
#' comparative ROC analysis. Essential for biomarker validation, diagnostic 
#' test evaluation, and clinical decision support in medical research.
#' 
#'
#' @examples
#' \donttest{
#' # pROC::aSAH ships with pROC, an Import, so the example runs in every module that
#' # carries this analysis. positiveClass is a Level option: always a required argument.
#' enhancedROC(
#'     data = pROC::aSAH,
#'     outcome = "outcome",
#'     positiveClass = "Poor",
#'     predictors = c("s100b", "ndka"))
#'}
#' @param data The data as a data frame.
#' @param outcome Outcome variable (disease status). A factor with two levels,
#'   or with more than two (choose one as Positive class and the others are
#'   pooled as negative, or use Multi-class ROC). A numeric outcome must have
#'   exactly two values; 0/1 reads 1 as positive. Each row must be a different
#'   patient: every interval and test assumes independent rows.
#' @param positiveClass Level of outcome treated as the positive class
#'   (condition present), matched exactly. Pass NULL to leave it unset: a
#'   numeric outcome coded 0/1 then reads 1 as positive, and any other outcome
#'   leaves the analysis waiting for a choice, because levels are never chosen
#'   from their order. Every other level is analysed as negative (pooled when
#'   there are more than two). A numeric outcome must have exactly two values;
#'   to choose among more, make it a factor.
#' @param predictors Numeric predictor variables for ROC analysis, one value
#'   per patient (row).
#' @param analysisType Single analyses each predictor on its own; Comparative
#'   adds the pairwise comparison tables and the comparative ROC plot.
#'   Comprehensive Diagnostic Performance currently gives the same output as
#'   Single.
#' @param direction Direction of the predictor-outcome relationship. The
#'   default is "Higher values indicate positive outcome" because it is a stated
#'   hypothesis rather than an estimate. "Auto" reads the orientation off the
#'   same data that supply the AUC - pROC compares the two groups' median values
#'   - so the direction is fitted rather than assumed, and every AUC is biased
#'   upward (for n = 20 the AUC expected under no association is about 0.60, not
#'   0.50, and exceeds 0.60 in roughly 45 of every 100 markers carrying no
#'   information at all). It is not floored at 0.5 either: a median split can
#'   disagree with the ranks, so about 12 of those 100 null markers are still
#'   reported below 0.5. "Auto" can also silently invert a marker and report
#'   0.825 where the un-inverted reading is 0.175. Use "Auto" only for
#'   exploratory screening of markers whose direction is genuinely unknown, and
#'   say so.
#' @param youdenOptimization Find the optimal cutoff by maximising the Youden
#'   index (sensitivity + specificity - 1), subject to the minimum
#'   sensitivity/specificity below. When off, the cutoff closest to the top-left
#'   corner of the ROC curve is reported instead. The minimum sensitivity and
#'   specificity are used only by the Youden search; with this off they are not
#'   applied and a warning says so.
#' @param customCutoffs Comma-separated list of custom cutoffs to evaluate
#'   (e.g., 0.1, 0.5, 0.9)
#' @param sensitivityThreshold Minimum sensitivity a cutoff must achieve to be
#'   considered. 0 (the default) searches for the overall Youden optimum with no
#'   constraint. Raising it restricts the search, which is what you want for a
#'   screening test, but the reported cutoff is then the best one meeting your
#'   minimum rather than the Youden maximum - a notice says so when the two
#'   differ. Used only when Youden index optimization is on.
#' @param specificityThreshold Minimum specificity a cutoff must achieve to be
#'   considered. 0 (the default) searches for the overall Youden optimum with no
#'   constraint. Raising it restricts the search, which is what you want for a
#'   confirmatory test, but the reported cutoff is then the best one meeting
#'   your minimum rather than the Youden maximum - a notice says so when the two
#'   differ. Used only when Youden index optimization is on.
#' @param confidenceLevel Confidence level for AUC confidence intervals
#' @param bootstrapSamples Number of resamples for every resampling step
#'   except the frozen-model report: bootstrap confidence intervals (AUC,
#'   partial AUC, multi-class), the ROC confidence bands, the bootstrap
#'   comparison test, and the number of permutations for Venkatraman's test.
#'   With B permutations no p-value below 1/(B + 1) can be shown, so keep at
#'   least 1000 for a test.
#' @param useBootstrap Use bootstrap methods for confidence intervals
#' @param bootstrapMethod Method for calculating bootstrap confidence
#'   intervals. BCa corrects for bias and skewness and is second-order accurate
#'   in large samples; for a single AUC in small samples no interval method is
#'   uniformly best (Obuchowski and Lieber 1998; Feng et al. 2017).
#' @param bootstrapPartialAUC Bootstrap confidence interval for the partial
#'   AUC, using the resample count, interval type (BCa/percentile/basic) and
#'   stratification set above. The interval is for the raw partial AUC on the
#'   chosen focus range, not for the McClish-normalised value.
#' @param stratifiedBootstrap Resample cases and controls separately, keeping
#'   the outcome proportions, in every bootstrap of this analysis: the AUC and
#'   partial-AUC intervals, the bootstrap comparison test and the ROC confidence
#'   bands (recommended for imbalanced data). Off by default: unticked, these
#'   bootstraps resample patients without regard to outcome.
#' @param seed Random seed used for every resampling step - bootstrap
#'   confidence intervals, bootstrap ROC comparisons, and internal validation
#'   resamples or cross-validation folds. Each step starts from this seed, so a
#'   predictor's result does not depend on which predictors or options were
#'   resampled before it. Fixing it makes a run reproducible: the same data and
#'   options give the same intervals every time. Change it to check how
#'   sensitive a result is to the particular resamples drawn.
#' @param pairwiseComparisons Perform pairwise comparisons between ROC curves
#' @param comparisonMethod Method for comparing ROC curves. DeLong et al.
#'   (1988) and Bootstrap test whether the two AUCs differ. The Venkatraman
#'   permutation test (Venkatraman & Begg 1996, paired data) tests whether the
#'   two ROC curves are identical over their whole range, not whether their AUCs
#'   differ.
#' @param rocCurve Display ROC curve plot
#' @param aucTable Display AUC summary table
#' @param cutoffTable Display detailed cutoff analysis
#' @param optimalCutoffs Display optimal cutoff summary
#' @param diagnosticMetrics Display comprehensive diagnostic metrics
#' @param clinicalMetrics Display clinical application metrics (PPV, NPV, LR+,
#'   LR-)
#' @param smoothMethod Method for smoothing ROC curves
#' @param partialAuc Calculate partial AUC for specific
#'   sensitivity/specificity ranges
#' @param partialAucType Whether to calculate pAUC over a specificity or
#'   sensitivity range
#' @param partialRange Range for partial AUC (min,max) - e.g., 0.8,1.0 for
#'   high specificity or sensitivity
#' @param crocAnalysis Calculate Concentrated ROC curves for early retrieval
#'   analysis
#' @param crocAlpha Concentration parameter for CROC exponential magnifier
#'   function
#' @param convexHull Calculate the ROC convex hull (operating points reachable
#'   by randomly mixing two cut-offs; in-sample, so optimistic)
#' @param detectImbalance Automatically detect class imbalance and recommend
#'   PRC when appropriate
#' @param imbalanceThreshold Ratio threshold for imbalance detection (e.g.,
#'   3.0 means 3:1 or 1:3 ratio)
#' @param showImbalanceWarning Add the explanatory detail to the
#'   class-imbalance warning. The warning itself is always shown when imbalance
#'   is detected; this only controls how much it explains.
#' @param recommendPRC Recommend adding the Precision-Recall curve alongside
#'   the ROC curve when imbalance is detected.
#' @param prevalence Disease prevalence to assume when computing predictive
#'   values. Used only when "Use observed prevalence" is unticked - set it to
#'   the prevalence of the population the test will actually be used in, which
#'   for a screening setting is usually far lower than in a case-control sample.
#' @param useObservedPrevalence Compute PPV, NPV and the clinical impact
#'   metrics at the prevalence observed in these data (the default). Untick it
#'   to assume a different prevalence instead - appropriate when the sample is
#'   enriched for cases and does not reflect the population the test will be
#'   used in. The prevalence actually used is printed in the results.
#' @param clinicalContext Clinical application context for interpretation
#' @param clinicalPresets Sets how the optimal cutoff is searched for: each
#'   preset turns Youden index optimization on and sets the minimums (Screening:
#'   sensitivity 0.90; Diagnostic validation: 0.80 and 0.80; Confirmatory:
#'   specificity 0.95; Research: keeps the minimums you enter, so it differs
#'   from Custom only by switching Youden optimization on). No other option
#'   changes.
#' @param comprehensive_output Include comprehensive statistical details
#' @param clinical_interpretation Provide clinical context for ROC analysis
#'   results
#' @param showAnalysisSummary A plain-language summary of the main results:
#'   the best AUC with its interval and the cutoff with its sensitivity and
#'   specificity. Internal validation results appear in the same panel whenever
#'   Internal validation is ticked.
#' @param showClinicalReport Copy-ready Methods and Results sentences built
#'   from these results. Check them against the tables before pasting them into
#'   a report.
#' @param showTableNotes Show explanatory notes and cell footnotes below the
#'   results tables, including methods, definitions and cautions for reading
#'   each table. The random seed of a resampled result is always shown.
#' @param plotTheme Visual theme for ROC plots
#' @param plotWidth Width of ROC plots
#' @param plotHeight Height of ROC plots
#' @param showCutoffPoints Highlight optimal cutoff points on ROC curve
#' @param showConfidenceBands Display confidence bands around ROC curve
#' @param showMetricsDiff Display detailed differences between model metrics
#' @param statisticalComparison Perform comprehensive statistical comparison
#'   between models
#' @param calibrationAnalysis Assess calibration (agreement between observed
#'   and predicted probabilities)
#' @param calibrationPlot Display the calibration plot: observed proportion
#'   against predicted probability in the Hosmer-Lemeshow risk groups, with an
#'   optional flexible spline curve (splineCalibration)
#' @param hosmerLemeshow Perform Hosmer-Lemeshow goodness-of-fit test
#' @param hlGroups Number of equal-sized risk groups used both for the
#'   Hosmer-Lemeshow test and for binning the calibration plot
#' @param brierScore Calculate Brier score and scaled Brier score
#' @param calibrationMetrics Calculate calibration slope, intercept, and
#'   calibration-in-the-large
#' @param splineCalibration Fit a flexible calibration curve by logistic
#'   regression of the outcome on a natural cubic spline of the logit of the
#'   predicted probability, a variant of the flexible calibration curves of
#'   Austin & Steyerberg (2019), who used loess and restricted cubic splines on
#'   the probability scale. Adds the smooth curve to the calibration plot and
#'   the integrated calibration index (ICI, the mean absolute difference between
#'   the curve and the diagonal) with E50, E90 and Emax to the calibration
#'   summary. Requires calibrationAnalysis.
#' @param splineKnots Knots of the spline calibration curve (3 to 7). The
#'   spline has knots - 1 degrees of freedom; more knots follow the data more
#'   closely but need more events per knot. Used only when splineCalibration is
#'   on.
#' @param eoRatio Expected/Observed ratio for overall calibration. Reported
#'   only when the predictor is supplied as a probability in 0 to 1; when a
#'   logistic model has to be fitted here to get probabilities the ratio is 1 by
#'   construction and the cell is left blank.
#' @param calibrationDensity Overlay the distribution of predicted
#'   probabilities along the bottom of the calibration plot, so a calibration
#'   point backed by two patients is not read like one backed by two hundred.
#'   Skipped when there are fewer than 10 usable probabilities to smooth.
#' @param multiClassROC Enable multi-class ROC analysis for outcomes with >2
#'   levels
#' @param multiClassStrategy Strategy for multi-class ROC analysis
#' @param multiClassAveraging Method for averaging AUC across classes. Both
#'   averages are reported side by side for the One-vs-Rest strategy: Macro
#'   weights every class equally, Weighted weights each class by how many cases
#'   it contains. The One-vs-One strategy reports only its own unweighted
#'   average over class pairs, which is what that statistic is defined as. Both
#'   averages are always shown, so this setting changes no displayed value; with
#'   One-vs-One, Weighted only raises a notice.
#' @param clinicalImpact Calculate observed or projected workload at
#'   independently supplied score cutoffs
#' @param nntCalculation Show inverse net benefit and inverse Youden index;
#'   neither is a count of tests or reviews
#' @param clinicalUtilityCurve Display clinical utility curve showing test
#'   consequences
#' @param decisionImpactTable Show decision impact at various thresholds
#' @param internalValidation Perform internal validation using
#'   cross-validation or bootstrap
#' @param validationMethod Bootstrap: Harrell's optimism-corrected AUC of a
#'   logistic model of the marker (resamples holding one outcome group are
#'   dropped and counted). Cross-validation: stratified 10-fold, or one fold per
#'   patient of the smaller outcome group when it has fewer than 10, reporting
#'   the mean fold AUC and the SD across folds, which is not a standard error.
#' @param decisionImpactCurves Plot the clinical impact curve: how many of
#'   1000 tested patients would be called high risk at each threshold
#'   probability, and how many of those actually have the event.
#' @param impactCutoffs Fixed score cutoffs on the marker's own scale, comma
#'   separated. The default 0.5 is meant for predicted probabilities (Prediction
#'   scale = probability); for a raw marker enter cutoffs inside its observed
#'   range. A warning names any cutoff that classifies every analysed patient
#'   the same way.
#' @param utilityThreshold Threshold probability for net benefit: the risk at
#'   which a clinician is indifferent between acting and not acting, so its odds
#'   are the harm of a false positive relative to the benefit of a true positive
#'   (0.1 means one true positive is worth nine false positives). Used by the
#'   clinical impact and workload tables; it is not a score cutoff.
#' @param workloadPopulationSize Size of the population the projected workload
#'   counts are scaled to. Used for every projected row: the main prevalence
#'   when Observed prevalence is unticked, and every additional target
#'   prevalence. Observed rows count the analysed patients instead.
#' @param analysisUnit What one row is (slide, core, patient...). Printed in
#'   the frozen-model report; every analysed row weighs equally in its metrics.
#' @param prevalenceScenarios Extra target-population prevalences, as
#'   proportions between 0 and 1 separated by commas (for example 0.05, 0.2).
#'   Each adds projected rows to the workload table at the same fixed cutoffs.
#'   Leave blank for none; an unreadable entry is ignored with a warning.
#' @param validationPanel Evaluates an already-fitted model or score at
#'   prespecified fixed cutoffs, without refitting or choosing a cutoff from
#'   these data, and replaces every other output with the validation context,
#'   denominator ledger and frozen-model metrics. Needs a positive class, an
#'   explicit negative level, an explicit Direction and the fixed score cutoffs.
#' @param validationNegative The outcome level that means the condition is
#'   absent, typed exactly as it appears in the data. Required by the
#'   frozen-model report, which refuses any outcome level that is neither this
#'   nor the positive class instead of pooling it as negative.
#' @param referenceDescription Free text describing the reference standard and
#'   whether its readers were blinded to the score (for example histology,
#'   blinded). Printed in the frozen-model validation context.
#' @param modelVersion Identifier of the fitted model or score version being
#'   evaluated. Required when Cohort role is frozen, so the report names exactly
#'   which model the metrics belong to.
#' @param cohortRole Declared by you and printed in the frozen-model report;
#'   the analysis does not check it. A value left at its default is printed as
#'   (default setting).
#' @param samplingDesign Declared by you and printed in the frozen-model
#'   report; the analysis does not check it. A value left at its default is
#'   printed as (default setting). The default is Other / unknown so that an
#'   untouched report does not assert a sampling design; how PPV and NPV should
#'   be read depends on it.
#' @param thresholdSource Declared by you and printed in the frozen-model
#'   report; the analysis does not check it. A value left at its default is
#'   printed as (default setting).
#' @param predictionScale What the predictor values are. Score (default) is
#'   any marker or model score: the calibration summary and plot, Brier score,
#'   E/O ratio, Hosmer-Lemeshow test and the decision and clinical impact curves
#'   then use risks from a logistic model of the score fitted to these data
#'   (in-sample). Probability means the values are predicted probabilities of
#'   the selected positive class, assessed as supplied; a predictor with a value
#'   outside 0 to 1 gets none of those outputs, and a probability is never
#'   reversed. Values between 0 and 1 are not taken as probabilities unless this
#'   says so. Frozen-model validation uses the same setting.
#' @param patientID Patient identifier. On the main analysis it is used only
#'   to warn when a patient has several rows: every panel except the
#'   Frozen-model validation report treats each row as an independent patient,
#'   so their intervals and tests are too narrow then. Only the Frozen-model
#'   validation report resamples whole patients.
#' @param siteID Optional site or centre of each row. The frozen-model report
#'   then adds one set of metrics per site, conditional on the observed sites,
#'   and resamples within sites. Every row needs a site, and a patient may not
#'   appear at two sites.
#' @param partitionID Optional development or validation label of each row,
#'   used by the frozen-model report to check that no patient appears in more
#'   than one partition (leakage). Requires a patient identifier.
#' @param validationBootstrap Adds percentile confidence intervals to the
#'   frozen-model metrics, resampling whole patients when a patient identifier
#'   is given (jointly across models, within sites). Without it the report shows
#'   point estimates only.
#' @param validationDraws Number of patient-level bootstrap replicates for the
#'   frozen-model intervals. Separate from Bootstrap samples, which serves the
#'   other panels.
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$results$notices} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$results$instructions} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$results$outcomeCoding} \tab \tab \tab \tab \tab Outcome levels with their counts and the role each plays in the analysis \cr
#'   \code{results$results$imbalanceMetrics} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$results$precisionRecallTable} \tab \tab \tab \tab \tab Metrics for imbalanced data analysis \cr
#'   \code{results$results$analysisSummary} \tab \tab \tab \tab \tab Plain language summary of key findings \cr
#'   \code{results$results$clinicalReport} \tab \tab \tab \tab \tab Copy-ready clinical report sentences for publications and reports \cr
#'   \code{results$results$aucSummary} \tab \tab \tab \tab \tab AUC values with confidence intervals for each predictor \cr
#'   \code{results$results$rocComparisons} \tab \tab \tab \tab \tab Pairwise comparisons between ROC curves \cr
#'   \code{results$results$detailedComparison} \tab \tab \tab \tab \tab Comprehensive comparison of diagnostic metrics between models \cr
#'   \code{results$results$statisticalSummary} \tab \tab \tab \tab \tab Summary of statistical tests for model comparison \cr
#'   \code{results$results$optimalCutoffSummary} \tab \tab \tab \tab \tab Youden Index optimization results for each predictor \cr
#'   \code{results$results$cutoffAnalysis} \tab \tab \tab \tab \tab Comprehensive analysis across multiple cutoff values \cr
#'   \code{results$results$diagnosticPerformance} \tab \tab \tab \tab \tab Comprehensive diagnostic performance measures at optimal cutoff \cr
#'   \code{results$results$clinicalApplicationMetrics} \tab \tab \tab \tab \tab Clinical metrics including predictive values and likelihood ratios \cr
#'   \code{results$results$partialAucAnalysis} \tab \tab \tab \tab \tab Partial AUC analysis for specific sensitivity/specificity ranges \cr
#'   \code{results$results$crocAnalysisTable} \tab \tab \tab \tab \tab Concentrated ROC analysis with early retrieval focus \cr
#'   \code{results$results$convexHullTable} \tab \tab \tab \tab \tab ROC convex hull - operating points reachable by randomly mixing two cut-offs (in-sample) \cr
#'   \code{results$results$comprehensiveAnalysisSummary} \tab \tab \tab \tab \tab Enhanced statistical summary for comprehensive output \cr
#'   \code{results$results$clinicalInterpretationGuide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$results$methodsExplanation} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$results$rocCurvePlot} \tab \tab \tab \tab \tab ROC curves with optimal cutoff points \cr
#'   \code{results$results$prcPlot} \tab \tab \tab \tab \tab Precision-Recall curve for imbalanced data \cr
#'   \code{results$results$comparativeROCPlot} \tab \tab \tab \tab \tab Multiple ROC curves for comparison \cr
#'   \code{results$results$cutoffAnalysisPlot} \tab \tab \tab \tab \tab Sensitivity and specificity across cutoff values \cr
#'   \code{results$results$youdenIndexPlot} \tab \tab \tab \tab \tab Youden Index values across cutoff range \cr
#'   \code{results$results$clinicalDecisionPlot} \tab \tab \tab \tab \tab Clinical decision curves and threshold analysis \cr
#'   \code{results$results$crocCurvePlot} \tab \tab \tab \tab \tab Concentrated ROC curve with exponential magnifier transformation \cr
#'   \code{results$results$convexHullPlot} \tab \tab \tab \tab \tab ROC curve with convex hull overlay \cr
#'   \code{results$results$calibrationSummary} \tab \tab \tab \tab \tab Overall calibration metrics including Brier score \cr
#'   \code{results$results$hosmerLemeshowTable} \tab \tab \tab \tab \tab Hosmer-Lemeshow test for calibration \cr
#'   \code{results$results$calibrationPlotImage} \tab \tab \tab \tab \tab Calibration plot showing observed vs predicted probabilities \cr
#'   \code{results$results$multiClassAUC} \tab \tab \tab \tab \tab AUC values for each class in multi-class analysis \cr
#'   \code{results$results$multiClassAverage} \tab \tab \tab \tab \tab Averaged AUC across all classes \cr
#'   \code{results$results$multiClassROCPlot} \tab \tab \tab \tab \tab ROC curves for all classes \cr
#'   \code{results$results$clinicalImpactTable} \tab \tab \tab \tab \tab Number needed to test and clinical utility metrics \cr
#'   \code{results$results$decisionImpactSummary} \tab \tab \tab \tab \tab Clinical consequences at various decision thresholds \cr
#'   \code{results$results$clinicalUtilityPlot} \tab \tab \tab \tab \tab Decision curve: net benefit against threshold probability \cr
#'   \code{results$results$decisionImpactPlot} \tab \tab \tab \tab \tab Number of patients called high risk, and number of true events among them, per 1000 tested across threshold probabilities \cr
#'   \code{results$results$screeningWorkload} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$results$validationContext} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$results$denominatorLedger} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$results$frozenMetrics} \tab \tab \tab \tab \tab a table \cr
#' }
#'
#' @export
enhancedROC <- function(
    data,
    outcome,
    positiveClass,
    predictors,
    analysisType = "single",
    direction = "higher",
    youdenOptimization = TRUE,
    customCutoffs = "",
    sensitivityThreshold = 0,
    specificityThreshold = 0,
    confidenceLevel = 95,
    bootstrapSamples = 1000,
    useBootstrap = FALSE,
    bootstrapMethod = "bca",
    bootstrapPartialAUC = FALSE,
    stratifiedBootstrap = FALSE,
    seed = 0,
    pairwiseComparisons = FALSE,
    comparisonMethod = "delong",
    rocCurve = TRUE,
    aucTable = TRUE,
    cutoffTable = FALSE,
    optimalCutoffs = TRUE,
    diagnosticMetrics = TRUE,
    clinicalMetrics = FALSE,
    smoothMethod = "none",
    partialAuc = FALSE,
    partialAucType = "specificity",
    partialRange = "0.8,1.0",
    crocAnalysis = FALSE,
    crocAlpha = 7,
    convexHull = FALSE,
    detectImbalance = FALSE,
    imbalanceThreshold = 3,
    showImbalanceWarning = FALSE,
    recommendPRC = FALSE,
    prevalence = 0.1,
    useObservedPrevalence = TRUE,
    clinicalContext = "general",
    clinicalPresets = "custom",
    comprehensive_output = FALSE,
    clinical_interpretation = FALSE,
    showAnalysisSummary = FALSE,
    showClinicalReport = FALSE,
    showTableNotes = FALSE,
    plotTheme = "clinical",
    plotWidth = 600,
    plotHeight = 600,
    showCutoffPoints = FALSE,
    showConfidenceBands = FALSE,
    showMetricsDiff = FALSE,
    statisticalComparison = FALSE,
    calibrationAnalysis = FALSE,
    calibrationPlot = FALSE,
    hosmerLemeshow = FALSE,
    hlGroups = 10,
    brierScore = FALSE,
    calibrationMetrics = FALSE,
    splineCalibration = FALSE,
    splineKnots = 4,
    eoRatio = FALSE,
    calibrationDensity = FALSE,
    multiClassROC = FALSE,
    multiClassStrategy = "ovr",
    multiClassAveraging = "macro",
    clinicalImpact = FALSE,
    nntCalculation = FALSE,
    clinicalUtilityCurve = FALSE,
    decisionImpactTable = FALSE,
    internalValidation = FALSE,
    validationMethod = "bootstrap",
    decisionImpactCurves = FALSE,
    impactCutoffs = "0.5",
    utilityThreshold = 0.1,
    workloadPopulationSize = 1000,
    analysisUnit = "slide",
    prevalenceScenarios = "",
    validationPanel = FALSE,
    validationNegative = "",
    referenceDescription = "",
    modelVersion = "",
    cohortRole = "frozen",
    samplingDesign = "other",
    thresholdSource = "prespecified",
    predictionScale = "score",
    patientID = NULL,
    siteID = NULL,
    partitionID = NULL,
    validationBootstrap = FALSE,
    validationDraws = 999) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("enhancedROC requires jmvcore to be installed (restart may be required)")

    if ( ! missing(outcome)) outcome <- jmvcore::resolveQuo(jmvcore::enquo(outcome))
    if ( ! missing(predictors)) predictors <- jmvcore::resolveQuo(jmvcore::enquo(predictors))
    if ( ! missing(patientID)) patientID <- jmvcore::resolveQuo(jmvcore::enquo(patientID))
    if ( ! missing(siteID)) siteID <- jmvcore::resolveQuo(jmvcore::enquo(siteID))
    if ( ! missing(partitionID)) partitionID <- jmvcore::resolveQuo(jmvcore::enquo(partitionID))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(outcome), outcome, NULL),
            `if`( ! missing(predictors), predictors, NULL),
            `if`( ! missing(patientID), patientID, NULL),
            `if`( ! missing(siteID), siteID, NULL),
            `if`( ! missing(partitionID), partitionID, NULL))


    options <- enhancedROCOptions$new(
        outcome = outcome,
        positiveClass = positiveClass,
        predictors = predictors,
        analysisType = analysisType,
        direction = direction,
        youdenOptimization = youdenOptimization,
        customCutoffs = customCutoffs,
        sensitivityThreshold = sensitivityThreshold,
        specificityThreshold = specificityThreshold,
        confidenceLevel = confidenceLevel,
        bootstrapSamples = bootstrapSamples,
        useBootstrap = useBootstrap,
        bootstrapMethod = bootstrapMethod,
        bootstrapPartialAUC = bootstrapPartialAUC,
        stratifiedBootstrap = stratifiedBootstrap,
        seed = seed,
        pairwiseComparisons = pairwiseComparisons,
        comparisonMethod = comparisonMethod,
        rocCurve = rocCurve,
        aucTable = aucTable,
        cutoffTable = cutoffTable,
        optimalCutoffs = optimalCutoffs,
        diagnosticMetrics = diagnosticMetrics,
        clinicalMetrics = clinicalMetrics,
        smoothMethod = smoothMethod,
        partialAuc = partialAuc,
        partialAucType = partialAucType,
        partialRange = partialRange,
        crocAnalysis = crocAnalysis,
        crocAlpha = crocAlpha,
        convexHull = convexHull,
        detectImbalance = detectImbalance,
        imbalanceThreshold = imbalanceThreshold,
        showImbalanceWarning = showImbalanceWarning,
        recommendPRC = recommendPRC,
        prevalence = prevalence,
        useObservedPrevalence = useObservedPrevalence,
        clinicalContext = clinicalContext,
        clinicalPresets = clinicalPresets,
        comprehensive_output = comprehensive_output,
        clinical_interpretation = clinical_interpretation,
        showAnalysisSummary = showAnalysisSummary,
        showClinicalReport = showClinicalReport,
        showTableNotes = showTableNotes,
        plotTheme = plotTheme,
        plotWidth = plotWidth,
        plotHeight = plotHeight,
        showCutoffPoints = showCutoffPoints,
        showConfidenceBands = showConfidenceBands,
        showMetricsDiff = showMetricsDiff,
        statisticalComparison = statisticalComparison,
        calibrationAnalysis = calibrationAnalysis,
        calibrationPlot = calibrationPlot,
        hosmerLemeshow = hosmerLemeshow,
        hlGroups = hlGroups,
        brierScore = brierScore,
        calibrationMetrics = calibrationMetrics,
        splineCalibration = splineCalibration,
        splineKnots = splineKnots,
        eoRatio = eoRatio,
        calibrationDensity = calibrationDensity,
        multiClassROC = multiClassROC,
        multiClassStrategy = multiClassStrategy,
        multiClassAveraging = multiClassAveraging,
        clinicalImpact = clinicalImpact,
        nntCalculation = nntCalculation,
        clinicalUtilityCurve = clinicalUtilityCurve,
        decisionImpactTable = decisionImpactTable,
        internalValidation = internalValidation,
        validationMethod = validationMethod,
        decisionImpactCurves = decisionImpactCurves,
        impactCutoffs = impactCutoffs,
        utilityThreshold = utilityThreshold,
        workloadPopulationSize = workloadPopulationSize,
        analysisUnit = analysisUnit,
        prevalenceScenarios = prevalenceScenarios,
        validationPanel = validationPanel,
        validationNegative = validationNegative,
        referenceDescription = referenceDescription,
        modelVersion = modelVersion,
        cohortRole = cohortRole,
        samplingDesign = samplingDesign,
        thresholdSource = thresholdSource,
        predictionScale = predictionScale,
        patientID = patientID,
        siteID = siteID,
        partitionID = partitionID,
        validationBootstrap = validationBootstrap,
        validationDraws = validationDraws)

    analysis <- enhancedROCClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

